#!/usr/bin/env python3
"""
Patch insight-dashboards: top 9 by views within rolling 30-day window.
Run via:
  git -C ~/medialibrary fetch origin
  git -C ~/medialibrary show origin/claude/youtube-vertical-dashboards-7YBYa:patch_insight.py | python3
"""
import base64, os, subprocess, sys
from pathlib import Path

ROOT = Path.home() / "insight-dashboards"

FILES = {
    'dashboards/youtube/api.py': '',
    'dashboards/youtube/cache.py': '',
    'dashboards/server.py': '',
    'frontend/youtube-shorts/index.html': '',
}
for rel, b64 in FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(b64))
    print(f"  updated {rel}")

os.chdir(ROOT)
for cmd in [
    ["git", "add", "-A"],
    ["git", "commit", "-m", "Top 9 by views in rolling 30-day window"],
    ["git", "push"],
]:
    r = subprocess.run(cmd, capture_output=True, text=True)
    print(r.stdout, end="")
    if r.returncode != 0:
        print(f"  [warn] {r.stderr.strip()}", file=sys.stderr)

print("\nDone. Now run:")
print("  sudo systemctl restart insight-dashboards")
print("  curl -X POST http://localhost:8001/api/youtube/refresh")
